-- Five IPA 2021-06-13 questions checked against the original paper.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2021-20210613-q14','exam-fe','デバイスドライバ','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問14・改編】デバイスドライバの役割はどれか。','[{"id":"a","text":"アプリケーションからの要求に従い、ハードウェアを直接制御する"},{"id":"b","text":"実行待ちタスクから次に実行するタスクを決める"},{"id":"c","text":"複数ウィンドウの画面表示状態を管理する"},{"id":"d","text":"入力されたコマンドを解釈し対応するプログラムを起動する"}]','"a"','デバイスドライバはハードウェアの制御を担当する。他はスケジューラ、ウィンドウ管理、シェルの役割。 中文：驱动程序控制硬件；其余分别是调度、窗口管理和命令解释。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q15','exam-fe','フェールセーフ','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問15・改編】フェールセーフの考え方はどれか。','[{"id":"a","text":"障害発生時にもシステムを安全側に制御する"},{"id":"b","text":"異常時に機能を縮退して運用を継続する"},{"id":"c","text":"重要な構成要素を複数備えて信頼性を高める"},{"id":"d","text":"誰が操作しても誤動作しにくい設計にする"}]','"a"','障害時に安全側へ制御することがフェールセーフ。縮退運転はフェールソフト、誤操作対策はフールプルーフ。 中文：故障时进入安全状态是故障安全；降级运行和防误操作是其他概念。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q17','exam-fe','スプーリング','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問17・改編】スプーリング機能の説明はどれか。','[{"id":"a","text":"入出力待ちでCPUが空いたとき別のタスクを実行する"},{"id":"b","text":"実行中のプログラムを中断し制御プログラムへ制御を移す"},{"id":"c","text":"主記憶と低速の入出力装置の間のデータ転送に補助記憶を介し、処理能力を高める"},{"id":"d","text":"主記憶上のバッファプールを使って補助記憶へのアクセス時間を短縮する"}]','"c"','スプーリングは補助記憶を待ち行列として使い、CPU処理と低速装置の処理を分離する。 中文：假脱机借助辅助存储暂存数据，使高速处理和低速外设并行。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q18','exam-fe','ページ置換','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問18・改編】仮想記憶のページ置換方式のうち、最後に使われてから最も長時間経過したページを入れ替える方式はどれか。','[{"id":"a","text":"FIFO"},{"id":"b","text":"LFU"},{"id":"c","text":"LIFO"},{"id":"d","text":"LRU"}]','"d"','LRUは最も長く参照されていないページを置換する。FIFOは到着順、LFUは参照回数に基づく。 中文：LRU替换最长时间未使用的页面。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q19','exam-fe','コンパイラ最適化','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問19・改編】コンパイラにおける最適化の説明はどれか。','[{"id":"a","text":"オブジェクトコードの代わりにインタプリタ用中間コードを作る"},{"id":"b","text":"コンパイル実行機と異なるアーキテクチャ向けのコードを作る"},{"id":"c","text":"ソースコードを解析し実行時の処理効率を高めたコードを作る"},{"id":"d","text":"実行時に呼出し名や変数値を表示するコードを作る"}]','"c"','最適化は意味を保ちながら実行効率などを改善する。異なる構成向けの生成はクロスコンパイル。 中文：编译优化在保持程序语义的同时改进执行效率；跨架构生成是交叉编译。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption');
